#include <stdio.h>

/* conceitoDaNota le a nota digitada e imprime o conceito:
   9 ou 10 -> A · 7 ou 8 -> B · 5 ou 6 -> C · abaixo de 5 -> D
   A primeira faixa ja esta escrita — continue a cascata. */
void conceitoDaNota(void) {
    int nota = 0;
    scanf("%d", &nota);

    if (nota >= 9) {
        printf("A\n");
    }
    /* continue daqui: else if para o B, else if para o C
       e o else final para o D */
}

