#include <stdio.h>

void conceitoDaNota(void) {
    int nota = 0;
    scanf("%d", &nota);

    if (nota >= 9) {
        printf("A\n");
    } else if (nota >= 7) {
        printf("B\n");
    } else if (nota >= 5) {
        printf("C\n");
    } else {
        printf("D\n");
    }
}
